#!/usr/bin/env python3
"""Embed saved, receipt-checked renders into an offline decision page."""
from pathlib import Path
import hashlib,json,base64,re
HERE=Path(__file__).resolve().parent
payload=json.loads(re.search(r'<script id="payload" type="application/json">(.*?)</script>',(HERE/'scenes.html').read_text(),re.S)[1])
def fig(key,caption):
 p=HERE/'renders'/f'{key}.png';r=json.loads(p.with_suffix('.json').read_text());assert r['input']==payload['scenes'][key]['digest'] and r['output']==hashlib.sha256(p.read_bytes()).hexdigest()
 return f'<figure><img src="data:image/png;base64,{base64.b64encode(p.read_bytes()).decode()}" alt="{caption}"><figcaption>{caption}</figcaption></figure>'
html='''<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Grudgelands · Torbogen und Dachfirst</title><style>body{margin:0;padding:40px;background:#171c20;color:#ede5d5;font:16px/1.55 system-ui;max-width:1600px;margin:auto}h1,h2{font-family:Georgia;color:#e8c58a}h1{font-size:36px}h2{margin-top:44px}p{max-width:1000px}a{color:#e8c58a}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}figure{margin:0;background:#222b31;border:1px solid #475057}img{width:100%;display:block}figcaption{padding:15px}code{color:#e6bb6d}.context{max-width:900px;margin:20px 0}table{border-collapse:collapse}td,th{padding:10px 20px;border-bottom:1px solid #475057;text-align:left}@media(max-width:850px){.pair{grid-template-columns:1fr}body{padding:20px}}</style>
<h1>Torbogen und Dachfirst</h1><p>Bestandsaufnahme und Vorschläge · Ausgelieferte Gebäude unverändert. Originale Spielbausteine, Texturen und Orientierungen im gemeinsamen Gebäude-Webrenderer; keine nachgezeichneten Ersatzmodelle.</p>
<p><a href="scenes.html">Interaktive 3D-Ansichten öffnen</a> · Ziehen: Kamera drehen · Mausrad: zoomen</p>
<h2>1 · Diese Stelle im Durchgang</h2><p>Wir schauen von außen in Richtung <code>+z</code>. Gold markiert die beiden Treppen direkt unter dem Sturz. Die Aussparungen laufen oben außen gegen die Seitenwand und bilden genau die kleinen Röhren. Lokale Positionen: links <code>x=4, y=5</code>, rechts <code>x=8, y=5</code>; jeweils über die gesamte Tiefe <code>z=0…6</code>.</p><div class="pair">'''
html+=fig('gate-current','Bestand · Links param2=1, rechts param2=3. Die Einkerbungen liegen oben zur Wand.')
html+=fig('gate-proposal','Vorschlag · Links param2=21, rechts param2=23. Umgedreht schließen die Treppen oben; die Abstufung öffnet sich nach unten zum Durchgang.')
html+='''</div><p><strong>Bitte zunächst die Stelle bestätigen.</strong> Die rechte Ansicht ist nur eine Vorschau. Treppen für den Aufgang in den seitlichen Wachraum sind nicht betroffen.</p><p>Gleiche fehlerhafte Anordnung in Highcourt, Dur Brannoc, Lethariel, Gor Drazhak und Nhal Veyr: 14 Treppen pro Tor-Template. Kezamba verwendet ein anderes Torhaus ohne diese Bogenanordnung.</p><div class="context">'''+fig('gate-context','Orientierung · Das untersuchte Tor im Hauptstadt-Kern, hier Highcourt.')+'''</div>
<h2>2 · Der tatsächlich schwebende Dachfirst</h2><p>Hier ist ein zwei Blöcke tiefer Querschnitt aus der Dachmitte zu sehen; Wände und andere Dachabschnitte sind nur für diese Ansicht ausgeblendet. Die zentrale Gruppe ist 1½ Blöcke hoch und beginnt einen halben Block oberhalb der seitlichen Dachflächen.</p><div class="pair">'''
html+=fig('ridge-current','Bestand · Zwischen seitlicher Dachfläche und zentralem First bleibt ½ Block Höhenlücke.')
html+=fig('ridge-proposal','Vorschlag · Die gesamte Firstgruppe um ½ Block abgesenkt. Ihre Unterkante erreicht die benachbarten Dachflächen.')
html+='''</div><p>Technisch reicht ein Tausch vorhandener Formen: bei <code>x=22, z=8…32</code> wird die obere Platte auf <code>y=27</code> zum Vollblock; der Vollblock auf <code>y=28</code> wird zur unteren Platte. Dadurch wandert die gleich hohe Gruppe exakt einen halben Block nach unten. Das Profil ist in allen sechs Königsburgen identisch.</p><table><tr><th></th><th>Unterkante</th><th>Oberkante</th></tr><tr><td>Bestand</td><td>27</td><td>28,5</td></tr><tr><td>Vorschlag</td><td>26,5</td><td>28</td></tr></table><div class="context">'''+fig('roof-context','Orientierung · Königsburg Highcourt. Der untersuchte First liegt längs auf der Haupthalle.')+'''</div><p>Diese Vorschau verändert weder Weltgeneration noch gespeicherte Welten. Eine spätere Übernahme in Gebäude-Templates muss als Änderung der Weltgeneration eingeordnet werden.</p></html>'''
(HERE/'index.html').write_text(html)
print('Offline gallery saved; six render hashes verified.')
